    {"q": "What do iridophores produce?", "options": ["Black pigment", "Shimmering, reflective blues and greens", "Venom", "Ink"], "answer": 1, "explain": ["Black comes from chromatophores.", "Correct. Thin plates reflect light like a soap bubble.", "Not related.", "Ink is stored in an ink sac."]},
    {"q": "What are papillae?", "options": ["Eyes", "Bumps in the skin that change texture", "Suckers", "Teeth"], "answer": 1, "explain": ["No.", "Correct. They let the octopus mimic coral, rock or seaweed in 3D.", "Suckers are on the arms but are different structures.", "Octopuses have a beak, not papillae teeth."]},
    {"q": "About what share of an octopus’s neurons are in its arms?", "options": ["None", "About one-tenth", "About two-thirds", "All of them"], "answer": 2, "explain": ["The arms are full of neurons.", "Much more than that.", "Correct. The arms can taste, feel and act semi-independently.", "The central brain has a large share too."]},
    {"q": "Which animal does the mimic octopus NOT typically imitate?", "options": ["Lionfish", "Sea snakes", "Flatfish", "Sharks"], "answer": 3, "explain": ["It does imitate lionfish.", "It does imitate sea snakes.", "It does imitate flatfish.", "Correct. Its known impressions include lionfish, sea snakes and flatfish."]}
